(144, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1169, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"video_poster\\\":\\\"\\\",\\\"video_src\\\":\\\"\\\"}\"}', '{\"content\":\"{\\\"title\\\":\\\"About the Community\\\",\\\"description\\\":\\\"A meticulously planned coastal sanctuary seamlessly integrating contemporary luxury living with untouched nature. Spanning scenic waterfronts, lush mangroves, and cycling corridors, the master community offers an unmatched urban lifestyle for residents and high-yield potential for global real estate investors.\\\",\\\"video_poster\\\":\\\"\\\\\\/images\\\\\\/projects\\\\\\/poster.jpg\\\",\\\"video_src\\\":\\\"\\\",\\\"heading\\\":\\\"About the Community\\\",\\\"video_url\\\":\\\"https:\\\\\\/\\\\\\/stream.mux.com\\\\\\/A3200aZtT5Wq7VlYwQv3wP9W2hX8.m3u8\\\",\\\"poster_image\\\":\\\"\\\\\\/images\\\\\\/projects\\\\\\/poster.jpg\\\"}\"}', 'https://saimaprojects.com/admin/cities', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-12 10:47:36', '2026-11-12 10:47:36'),
(145, 'App\\Models\\User', 2, 'updated', 'App\\Models\\PageSection', 1170, '{\"content\":\"{\\\"title\\\":\\\"\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[]}\"}', '{\"content\":\"{\\\"title\\\":\\\"Frequently Asked Questions\\\",\\\"description\\\":\\\"\\\",\\\"items\\\":[{\\\"q\\\":\\\"Are properties in this city freehold for foreign and overseas investors?\\\",\\\"a\\\":\\\"Yes, designated luxury master developments offer 100% freehold ownership for local and international buyers with complete title deed registration.\\\"},{\\\"q\\\":\\\"What are the typical payment plans available?\\\",\\\"a\\\":\\\"Flexible installment plans are offered typically linked to construction milestones, with down payments starting from 5% to 10%.\\\"}],\\\"heading\\\":\\\"Frequently Asked Questions\\\",\\\"subtitle\\\":\\\"Find answers to common questions about properties, buying process, and payment plans.\\\"}\"}', 'https://saimaprojects.com/admin/cities', '203.101.188.87', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/156.0.0.0 Safari/537.36', NULL, '2026-11-12 10:47:36', '2026-11-12 10:47:36'),
