usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:13:{i:0;s:5:\"title\";i:1;s:4:\"slug\";i:2;s:4:\"body\";i:3;s:9:\"in_navbar\";i:4;s:12:\"navbar_order\";i:5;s:12:\"is_published\";i:6;s:10:\"meta_title\";i:7;s:16:\"meta_description\";i:8;s:13:\"meta_keywords\";i:9;s:8:\"og_image\";i:10;s:6:\"status\";i:11;s:16:\"show_in_projects\";i:12;s:18:\"show_in_commercial\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}s:21:\"\0*\0excludedAttributes\";a:0:{}s:10:\"auditEvent\";N;s:14:\"auditCustomOld\";N;s:14:\"auditCustomNew\";N;s:13:\"isCustomEvent\";b:0;s:21:\"preloadedResolverData\";a:0:{}}', 1794597548);
