(7, 'highlight_launch_price', 'highlights', 'Starting Price Badge', 'text', 'AED 4.3M', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(8, 'highlight_handover', 'highlights', 'Handover Badge', 'text', 'Q3 2030', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(9, 'highlight_property_type', 'highlights', 'Property Type Badge', 'text', 'Villas & Apartments', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
