(12, 'overview_heading', 'overview', 'Overview Section Heading', 'text', 'Hudayriyat Island Projects: The Residential Communities', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(13, 'overview_intro', 'overview', 'Overview Section Intro Paragraph', 'textarea', 'This is probably the section you\'ve been waiting for. Modon has rolled out its Hudayriyat Island projects in phases, each with its own character, price point, and target buyer. Here\'s a rundown of the main communities, based on details published on the island\'s official project pages.', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(14, 'investment_heading', 'investment', 'Investment Section Heading', 'text', 'Investment Potential & Flexible Financing Options', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(15, 'investment_subheading', 'investment', 'Investment Subheading', 'text', 'High-Yield Waterfront Capital Appreciation in the UAE Capital', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(16, 'investment_intro', 'investment', 'Investment Intro Text', 'textarea', 'Investing in Hudayriyat Island real estate represents a generational opportunity to acquire prime coastal freehold property in Abu Dhabi. Supported by government-backed infrastructure and world-class master planning by Modon Properties, capital values are poised for sustainable long-term appreciation.', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(17, 'contact_phone', 'contact', 'Official Contact Phone', 'text', '+971 50 123 4567', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(18, 'contact_email', 'contact', 'Official Contact Email', 'text', 'sales@hudayriyat.com', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(19, 'contact_address', 'contact', 'Office Address', 'text', 'Hudayriyat Island Sales Centre, Abu Dhabi, United Arab Emirates', '2026-10-20 03:31:31', '2026-10-20 03:31:31'),
(20, 'seo_title', 'seo', 'Page Title (<title>)', 'text', 'Hudayriyat Island – Luxury Villas & Waterfront Living in Abu Dhabi', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(21, 'seo_description', 'seo', 'Meta Description', 'textarea', 'Discover Hudayriyat Island, a premier luxury waterfront community in Abu Dhabi offering exclusive villas, mansions, and world-class amenities. Enjoy serene beaches, cultural heritage, and modern living in a secure and vibrant environment. Invest in your dream home today.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(22, 'hero_success_message', 'hero', 'Form Success Message', 'textarea', '✓ Your request has been received. Our luxury property specialist will call you back shortly!', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(23, 'highlight_1_label', 'highlights', 'Badge 1 – Label', 'text', 'Developer', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(24, 'highlight_1_value', 'highlights', 'Badge 1 – Value', 'text', 'Modon Properties', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(25, 'highlight_2_label', 'highlights', 'Badge 2 – Label', 'text', 'Launch Price', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(26, 'highlight_2_value', 'highlights', 'Badge 2 – Value', 'text', 'AED 4,300,000*', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
