(31, 'highlight_5_label', 'highlights', 'Badge 5 – Label', 'text', 'Ownership', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(32, 'highlight_5_value', 'highlights', 'Badge 5 – Value', 'text', 'Freehold', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(33, 'highlight_6_label', 'highlights', 'Badge 6 – Label', 'text', 'Payment Plan', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(34, 'highlight_6_value', 'highlights', 'Badge 6 – Value', 'text', '5% / 35% / 60%', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(35, 'investment_location_badge', 'investment', 'Location Badge', 'text', 'Hudayriyat Island, Abu Dhabi', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(36, 'investment_description', 'investment', 'Investment Description', 'textarea', 'Hudayriyat Island offers attractive real estate investment opportunities through its premium villa communities, waterfront lifestyle, and developments by Modon Properties. With growing interest in luxury coastal living in Abu Dhabi, the island presents opportunities for investors seeking long-term capital appreciation and potential rental income.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(37, 'investment_highlights_heading', 'investment', 'Highlights Heading', 'text', 'Key Investment Highlights:', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(38, 'investment_highlights', 'investment', 'Investment Highlights (one per line)', 'list', 'Premium villa communities with exclusive residential options\nDeveloped by Modon Properties\nStrong appeal among luxury homebuyers and property investors\nCoastal location with access to beaches and recreational facilities\nPotential for long-term capital appreciation\nAttractive lifestyle destination for families and investors\nGrowing residential and leisure destination in Abu Dhabi', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(39, 'investment_cta', 'investment', 'Investment Button Text', 'text', 'Contact a Property Investment Consultant', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(40, 'financing_title', 'investment', 'Financing Card Title', 'text', 'Flexible Financing Options', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(41, 'financing_description', 'investment', 'Financing Card Description', 'textarea', 'Buying an off-plan property or a ready-to-move-in home? Maximise your buying power with competitive mortgage options tailored to your needs.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(42, 'financing_highlights', 'investment', 'Financing Highlights (one per line)', 'list', 'Secure a mortgage during construction to maximize leverage\nCombine developer payment plans with tailored bank financing\nGet pre-approved in as little as 3 days\nConventional and Sharia-compliant financing available\nNo hidden fees or added costs', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(43, 'financing_cta', 'investment', 'Financing Button Text', 'text', 'Contact a Mortgage Specialist', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(44, 'contact_pretitle', 'contact', 'Pre-title', 'text', 'LET\'S CONNECT', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(45, 'contact_heading', 'contact', 'Heading (H2)', 'text', 'Invest in Your Future', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(46, 'contact_subtitle', 'contact', 'Subtitle Paragraph', 'textarea', 'Discover exceptional residential villas, waterfront mansions, and prime plots across Hudayriyat Island. Connect with our dedicated property advisory team for personalized guidance and private viewings.', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
(47, 'contact_form_title_small', 'contact', 'Form Title – Small', 'text', 'REQUEST', '2026-10-20 04:11:47', '2026-10-20 04:11:47'),
