(607, 80, 'about', 'About Community', 3, 1, '{\"title\":\"Saima Corporate Center by Saima Builders\",\"description\":\"<p>Saima Corporate Center is a mixed-use commercial tower at PIDC, Karachi, opposite Pearl Continental (PC) Hotel, offering corporate offices, retail shops, showrooms, and business suites under one roof by Saima Builders, featuring a prime central address in the heart of Karachi\'s commercial district.<\\/p>\",\"video_poster\":\"\\/uploads\\/pages\\/1793688896_6ae985409192c.jpg\",\"video_src\":\"\\/images\\/nawayef-park-views\\/asset_15.mp4\",\"video_url\":\"\\/images\\/nawayef-park-views\\/asset_15.mp4\"}', '2026-10-30 06:46:11', '2026-11-03 06:54:56'),
(608, 80, 'amenities', 'Amenities & Facilities', 4, 1, '{\"title\":\"Saima Corporate Center at PIDC Karachi Amenities\",\"subtitle\":\"Saima Corporate Center Karachi provides facilities that support everyday business operations, client handling, and professional working. Occupants can access a proper reception lobby, dedicated parking levels, modern high-speed lift access, wide corridors, recreational facilities, and clearly separated retail and office floors within the Saima Corporate Center development.\",\"items\":[]}', '2026-10-30 06:46:11', '2026-11-10 07:23:21'),
(609, 80, 'gallery', 'Project Gallery', 5, 1, '{\"title\":\"Project Gallery\",\"images\":[{\"src\":\"\\/uploads\\/pages\\/1793688896_6ae9854093db1.jpg\",\"category\":\"Exterior\",\"alt\":\"Project Photo\"},{\"src\":\"\\/uploads\\/pages\\/1793688896_6ae9854093fb1.jpg\",\"category\":\"Exterior\",\"alt\":\"Project Photo\"},{\"src\":\"\\/uploads\\/pages\\/1793688896_6ae9854094808.jpg\",\"category\":\"Exterior\",\"alt\":\"Project Photo\"}]}', '2026-10-30 06:46:11', '2026-11-03 06:54:56');
