(799, 101, 'about', 'About North Nazimabad', 4, 1, '{\"title\":\"About the Community\",\"description\":\"A meticulously planned coastal sanctuary seamlessly integrating contemporary luxury living with untouched nature. Spanning scenic waterfronts, lush mangroves, and cycling corridors, the master community offers an unmatched urban lifestyle for residents and high-yield potential for global real estate investors.\",\"video_poster\":\"\\/images\\/projects\\/poster.jpg\",\"video_src\":\"\",\"heading\":\"About the Community\",\"video_url\":\"https:\\/\\/stream.mux.com\\/A3200aZtT5Wq7VlYwQv3wP9W2hX8.m3u8\",\"poster_image\":\"\\/images\\/projects\\/poster.jpg\"}', '2026-11-03 07:26:08', '2026-11-03 07:26:08'),
(800, 101, 'faq', 'Frequently Asked Questions', 5, 1, '{\"title\":\"Frequently Asked Questions\",\"description\":\"\",\"items\":[{\"q\":\"Are properties in this city freehold for foreign and overseas investors?\",\"a\":\"Yes, designated luxury master developments offer 100% freehold ownership for local and international buyers with complete title deed registration.\"},{\"q\":\"What are the typical payment plans available?\",\"a\":\"Flexible installment plans are offered typically linked to construction milestones, with down payments starting from 5% to 10%.\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":\"Find answers to common questions about properties, buying process, and payment plans.\"}', '2026-11-03 07:26:08', '2026-11-03 07:26:08'),
(801, 101, 'contact', 'Contact & Booking CTA', 6, 1, '{\"title\":\"\",\"subtitle\":\"Connect with our dedicated city property advisors for personalized availability, floor plans, and VIP access.\",\"button_text\":\"\",\"phone\":\"+971 2 000 0000\",\"email\":\"info@hudayriyat-island.ae\"}', '2026-11-03 07:26:08', '2026-11-03 07:26:08'),
(802, 102, 'hero', 'Hero Banner & Form', 1, 1, '{\"title\":\"Saima Premium Empire at North Nazimabad Karachi\",\"subtitle\":\"Saima Premium Empire, 4, 5 & 6-room luxury apartments by Saima Builders in Block A, North Nazimabad, Karachi. See key details.\",\"badge\":null,\"bg_image\":\"\\/uploads\\/pages\\/1793691225_6ae98e59402cc.jpg\",\"bg_image_alt\":\"Saima Premium Empire at North Nazimabad Karachi\",\"image_alt\":\"Saima Premium Empire at North Nazimabad Karachi\"}', '2026-11-03 07:26:44', '2026-11-03 07:45:31'),
