(883, 110, 'about', 'About Scheme 33', 4, 1, '{\"title\":\"About the Community\",\"description\":\"A meticulously planned coastal sanctuary seamlessly integrating contemporary luxury living with untouched nature. Spanning scenic waterfronts, lush mangroves, and cycling corridors, the master community offers an unmatched urban lifestyle for residents and high-yield potential for global real estate investors.\",\"video_poster\":\"\\/images\\/projects\\/poster.jpg\",\"video_src\":\"\",\"heading\":\"About the Community\",\"video_url\":\"https:\\/\\/stream.mux.com\\/A3200aZtT5Wq7VlYwQv3wP9W2hX8.m3u8\",\"poster_image\":\"\\/images\\/projects\\/poster.jpg\"}', '2026-11-03 11:05:38', '2026-11-03 11:05:38'),
(884, 110, 'faq', 'Frequently Asked Questions', 5, 1, '{\"title\":\"Frequently Asked Questions\",\"description\":\"\",\"items\":[{\"q\":\"Are properties in this city freehold for foreign and overseas investors?\",\"a\":\"Yes, designated luxury master developments offer 100% freehold ownership for local and international buyers with complete title deed registration.\"},{\"q\":\"What are the typical payment plans available?\",\"a\":\"Flexible installment plans are offered typically linked to construction milestones, with down payments starting from 5% to 10%.\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":\"Find answers to common questions about properties, buying process, and payment plans.\"}', '2026-11-03 11:05:38', '2026-11-03 11:05:38'),
(885, 110, 'contact', 'Contact & Booking CTA', 6, 1, '{\"title\":\"\",\"subtitle\":\"Connect with our dedicated city property advisors for personalized availability, floor plans, and VIP access.\",\"button_text\":\"\",\"phone\":\"+971 2 000 0000\",\"email\":\"info@hudayriyat-island.ae\"}', '2026-11-03 11:05:38', '2026-11-03 11:05:38'),
(886, 111, 'hero', 'Hero Banner & Form', 1, 1, '{\"title\":\"Saima Boulevard at Scheme 33 Karachi\",\"subtitle\":\"Saima Boulevard by Saima Builders in Sector 29, Gulzar-e-Hijri, Scheme 33, Karachi, with 2, 3 & 4-bed apartments. See payment plan and details.\",\"badge\":null,\"bg_image\":\"\\/uploads\\/pages\\/1793704430_6ae9c1ee25317.jpg\",\"bg_image_alt\":\"Saima Boulevard at Scheme 33 Karachi\",\"image_alt\":\"Saima Boulevard at Scheme 33 Karachi\"}', '2026-11-03 11:05:58', '2026-11-03 11:14:02'),
